 ['id'=>'excellent','name'=>'Tốt','min_score'=>90,'color'=>'success'],['id'=>'good','name'=>'Khá','min_score'=>80,'color'=>'primary'],['id'=>'pass','name'=>'Đạt','min_score'=>65,'color'=>'warning'],['id'=>'fail','name'=>'Chưa đạt','min_score'=>0,'color'=>'danger']];

