function tdr_redirect(string $tab,array $extra=[]):void{header('Location: '.BASE_URL.'thidua_phongnoitru.php?'.http_build_query(['tab'=>$tab]+$extra));exit;}
function tdr_week(string $date):array{$w=csdl_week_for_date($date);if($w)return $w;$weeks=csdl_year_weeks();if($weeks){$sel=end($weeks);foreach($weeks as $x){$sel=$x;if(($x['start']??'')>=$date)break;}return $sel;}$t=strtotime($date)?:time();$s=date('Y-m-d',strtotime('monday this week',$t));return['start'=>$s,'end'=>date('Y-m-d',strtotime($s.' +6 days')),'label'=>'Tuần chưa cấu hình'];}
function tdr_dates(string $from,string $to):array{$out=[];$t=strtotime($from);$end=strtotime($to);while($t!==false&&$t<=$end){$out[]=date('Y-m-d',$t);$t=strtotime('+1 day',$t);}return$out;}
function tdr_ratings(array $s):array{$rows=array_values(array_filter((array)($s['ratings']??[]),fn($r)=>trim((string)($r['name']??''))!==''));$max=(float)($s['daily_max']??100);foreach($rows as &$r){if(!isset($r['min_score']))$r['min_score']=round($max*(float)($r['min_percent']??0)/100,2);}unset($r);usort($rows,fn($a,$b)=>(float)$b['min_score']<=>(float)$a['min_score']);return$rows;}
function tdr_rating(float $score,array $s):array{foreach(tdr_ratings($s) as $r)if($score>=(float)$r['min_score'])return$r;return['name'=>'Chưa xếp loại','color'=>'secondary'];}
function tdr_entry_key(array $e):string{return(string)($e['week_start']??'').'|'.(string)($e['room']??'');}
function tdr_find_entry(array $entries,string $weekStart,string $room):?int{foreach($entries as $i=>$e)if(tdr_entry_key($e)===$weekStart.'|'.$room)return$i;return null;}
function tdr_day_deduction(array $entry,string $date):float{$n=0;foreach((array)($entry['items']??[]) as $it)if((string)($it['date']??'')===$date)$n+=(float)($it['points']??0)*max(1,(int)($it['quantity']??1));return round($n,2);}
function tdr_day_score(?array $entry,string $date,array $settings):float{$max=(float)($settings['daily_max']??100);return max(0,round($max-($entry?tdr_day_deduction($entry,$date):0),2));}
function tdr_effective_dates(string $from,string $to,array $skip):array{$today=date('Y-m-d');$toEff=$to>$today?$today:$to;if($toEff<$from)return[];return array_values(array_filter(tdr_dates($from,$toEff),fn($d)=>!in_array($d,$skip,true)));}
function tdr_shift_label(string $s):string{return$s==='chieu'?'Chiều':'Sáng';}
function tdr_fmt(float $n,int $dec=1):string{return number_format($n,$dec,',','.');}

if(empty($_SESSION['td_room_csrf']))$_SESSION['td_room_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['td_room_csrf'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
 $action=(string)($_POST['action']??''); $actionTab=['batch_save'=>'input','skip_dates_save'=>'input','entry_delete'=>'input','settings_save'=>'settings'][$action]??'';
 if($actionTab===''||!in_array($actionTab,$allowedTabs,true)){http_response_code(403);exit('Không có quyền thực hiện thao tác này.');}
 $need=$action==='entry_delete'?'delete':'edit';if(!can_perm_level($permissions[$actionTab],$need)){http_response_code(403);exit('Tài khoản chưa có quyền '.$need.'.');}
 if($action==='settings_save'){
   $daily=max(1,(float)($_POST['daily_max']??100));$names=(array)($_POST['rating_name']??[]);$mins=(array)($_POST['rating_min']??[]);$colors=(array)($_POST['rating_color']??[]);$ratings=[];
   foreach($names as $i=>$name){$name=trim((string)$name);if($name==='')continue;$color=(string)($colors[$i]??'secondary');if(!in_array($color,['success','primary','info','warning','danger','secondary'],true))$color='secondary';$ratings[]=['id'=>'rr_'.bin2hex(random_bytes(4)),'name'=>$name,'min_score'=>max(0,min($daily,(float)($mins[$i]??0))),'color'=>$color];}
   if(!$ratings){flash('Cần ít nhất một mức xếp loại.','danger');tdr_redirect('settings');}usort($ratings,fn($a,$b)=>$b['min_score']<=>$a['min_score']);
   $ids=(array)($_POST['criterion_id']??[]);$cn=(array)($_POST['criterion_name']??[]);$cp=(array)($_POST['criterion_points']??[]);$ca=(array)($_POST['criterion_active']??[]);$criteria=[];
   foreach($cn as $i=>$name){$name=trim((string)$name);if($name==='')continue;$id=preg_replace('/[^a-zA-Z0-9_-]/','',(string)($ids[$i]??''));if($id==='')$id='rc_'.bin2hex(random_bytes(5));$criteria[]=['id'=>$id,'name'=>$name,'points'=>max(.01,(float)($cp[$i]??1)),'active'=>(string)($ca[$i]??'1')==='1'];}
   if(!$criteria){flash('Cần ít nhất một mục chấm.','danger');tdr_redirect('settings');}
   $data['settings']['daily_max']=$daily;$data['settings']['weekly_max']=$daily;$data['settings']['ratings']=$ratings;$data['criteria']=$criteria;save_json($dataFile,$data);flash('Đã lưu điểm chuẩn theo ngày và các mục chấm.','success');tdr_redirect('settings');
 }
 if($action==='skip_dates_save'){
   $weekStart=trim((string)($_POST['week_start']??''));$week=tdr_week($weekStart);$valid=tdr_dates($week['start'],$week['end']);$picked=array_values(array_intersect($valid,array_map('strval',(array)($_POST['skip_dates']??[]))));$data['skip_dates'][$week['start']]=$picked;save_json($dataFile,$data);flash('Đã cập nhật các ngày không chấm trong tuần.','success');tdr_redirect('input',['week'=>$week['start'],'day'=>(string)($_POST['day']??'')]);
 }
 if($action==='batch_save'){
   $date=trim((string)($_POST['date']??date('Y-m-d')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=date('Y-m-d');$week=tdr_week($date);$shift=in_array(($_POST['shift']??''),['sang','chieu'],true)?$_POST['shift']:'sang';
   $criterionId=(string)($_POST['criterion_id']??'');$criterion=null;foreach($data['criteria'] as $r)if(!empty($r['active'])&&(string)$r['id']===$criterionId)$criterion=$r;
   if(!$criterion){flash('Hãy chọn một mục chấm.','danger');tdr_redirect('input',['week'=>$week['start'],'day'=>$date]);}
   $selected=array_values(array_intersect($rooms,array_map('strval',(array)($_POST['rooms']??[]))));$roomPoints=(array)($_POST['room_points']??[]);$roomNotes=(array)($_POST['room_note']??[]);$max=(float)$data['settings']['daily_max'];
   foreach($selected as $room){$idx=tdr_find_entry($data['entries'],$week['start'],$room);if($idx===null){$data['entries'][]=['id'=>'tre_'.bin2hex(random_bytes(7)),'room'=>$room,'week_start'=>$week['start'],'week_end'=>$week['end'],'week_label'=>$week['label']??'','items'=>[],'created_by'=>$userName,'created_at'=>date('c')];$idx=array_key_last($data['entries']);}
     $points=max(.01,(float)($roomPoints[$room]??$criterion['points']));$found=null;foreach((array)$data['entries'][$idx]['items'] as $ii=>$it)if((string)($it['date']??'')===$date&&(string)($it['shift']??'sang')===$shift&&(string)($it['criterion_id']??'')===$criterionId){$found=$ii;break;}
     $item=['id'=>$found===null?'ri_'.bin2hex(random_bytes(5)):($data['entries'][$idx]['items'][$found]['id']??'ri_'.bin2hex(random_bytes(5))),'criterion_id'=>$criterionId,'name'=>(string)$criterion['name'],'points'=>$points,'quantity'=>1,'date'=>$date,'shift'=>$shift,'note'=>trim((string)($roomNotes[$room]??'')),'created_by'=>$userName,'created_at'=>$found===null?date('c'):($data['entries'][$idx]['items'][$found]['created_at']??date('c')),'updated_at'=>date('c')];
     if($found===null)$data['entries'][$idx]['items'][]=$item;else$data['entries'][$idx]['items'][$found]=$item;$data['entries'][$idx]['updated_by']=$userName;$data['entries'][$idx]['updated_at']=date('c');
   }
   $sessionKey=$week['start'].'|'.$date.'|'.$shift;$exists=false;foreach($data['sessions'] as &$s)if(($s['key']??'')===$sessionKey){$s['by']=$userName;$s['updated_at']=date('c');$exists=true;break;}unset($s);if(!$exists)$data['sessions'][]=['key'=>$sessionKey,'week_start'=>$week['start'],'date'=>$date,'shift'=>$shift,'by'=>$userName,'created_at'=>date('c')];
   save_json($dataFile,$data);flash('Đã lưu lần chấm '.tdr_shift_label($shift).' ngày '.date('d/m/Y',strtotime($date)).($selected?' cho '.count($selected).' phòng vi phạm.':'. Không có phòng vi phạm.'),'success');tdr_redirect('input',['week'=>$week['start'],'day'=>$date]);
 }
 if($action==='entry_delete'){$id=trim((string)($_POST['id']??''));$before=count($data['entries']);$data['entries']=array_values(array_filter($data['entries'],fn($r)=>(string)($r['id']??'')!==$id));if(count($data['entries'])<$before){save_json($dataFile,$data);flash('Đã xóa dữ liệu của phòng trong tuần.','warning');}else flash('Không tìm thấy dữ liệu.','warning');tdr_redirect('input',['week'=>(string)($_POST['week']??'')]);}
}

$weeks=csdl_year_weeks();$today=date('Y-m-d');$weekReq=(string)($_GET['week']??$today);$inputWeek=tdr_week($weekReq);$weekDates=tdr_dates($inputWeek['start'],$inputWeek['end']);$skipDates=array_values((array)($data['skip_dates'][$inputWeek['start']]??[]));$inputDateDefault=($today>=$inputWeek['start']&&$today<=$inputWeek['end'])?$today:$inputWeek['start'];$tableDay=(string)($_GET['day']??$inputDateDefault);if(!in_array($tableDay,$weekDates,true))$tableDay=$inputDateDefault;
$inputMap=[];foreach($data['entries'] as $e)if(($e['week_start']??'')===$inputWeek['start'])$inputMap[(string)($e['room']??'')]=$e;
$activeCriteria=array_values(array_filter($data['criteria'],fn($r)=>!empty($r['active'])));$ratings=tdr_ratings($data['settings']);$defaultCriterion=$activeCriteria[0]??null;

$statsMode=($_GET['mode']??'week')==='range'?'range':'week';$anchor=(string)($_GET['anchor']??$today);$statsWeek=tdr_week($anchor);$from=$statsMode==='week'?$statsWeek['start']:(string)($_GET['from']??date('Y-m-01'));$to=$statsMode==='week'?$statsWeek['end']:(string)($_GET['to']??$today);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$to<$from)$to=$from;
$summary=[];foreach($rooms as $room)$summary[$room]=['room'=>$room,'days'=>0,'total'=>0,'average'=>0,'deduction'=>0];
$rangeDates=tdr_dates($from,$to);foreach($rooms as $room){$scores=[];$ded=0;foreach($rangeDates as $d){if($d>$today)continue;$w=tdr_week($d);$skip=(array)($data['skip_dates'][$w['start']]??[]);if(in_array($d,$skip,true))continue;$entry=null;foreach($data['entries'] as $e)if(($e['week_start']??'')===$w['start']&&($e['room']??'')===$room){$entry=$e;break;}$scores[]=tdr_day_score($entry,$d,$data['settings']);if($entry)$ded+=tdr_day_deduction($entry,$d);}if($scores){$summary[$room]['days']=count($scores);$summary[$room]['total']=round(array_sum($scores),2);$summary[$room]['average']=round(array_sum($scores)/count($scores),2);$summary[$room]['deduction']=round($ded,2);$summary[$room]['rating_data']=tdr_rating($summary[$room]['average'],$data['settings']);}}
uasort($summary,function($a,$b){if(!$a['days']&&!$b['days'])return strnatcasecmp($a['room'],$b['room']);if(!$a['days'])return 1;if(!$b['days'])return -1;return($b['average']<=>$a['average'])?:strnatcasecmp($a['room'],$b['room']);});

$criterionRows=[];foreach($activeCriteria as $c)$criterionRows[(string)$c['id']]=$c;foreach($inputMap as $e)foreach((array)($e['items']??[]) as $it){$cid=(string)($it['criterion_id']??'legacy');if(!isset($criterionRows[$cid]))$criterionRows[$cid]=['id'=>$cid,'name'=>(string)($it['name']??'Mục chấm cũ'),'points'=>(float)($it['points']??0),'active'=>true];}
function tdr_cell(array $inputMap,string $room,string $day,string $shift,string $cid):array{$e=$inputMap[$room]??null;if(!$e)return[];$out=[];foreach((array)($e['items']??[]) as $it)if((string)($it['date']??'')===$day&&(string)($it['shift']??'sang')===$shift&&(string)($it['criterion_id']??'')===$cid)$out[]=$it;return$out;}
