"><?php foreach($data['criteria'] as $c):?><div class="setting-row"><input class="form-control criterion-id" name="criterion_id[]" value="<?=e($c['id'])?>" readonly><input class="form-control" name="criterion_name[]" value="<?=e($c['name'])?>" required><input class="form-control" type="number" min=".01" step=".01" name="criterion_points[]" value="<?=e($c['points'])?>" required><select class="form-select" name="criterion_active[]"><option value="1" <?=!empty($c['active'])?'selected':''?>>Hiển thị</option><option value="0" <?=empty($c['active'])?'selected':''?>>Ẩn</option></select><button class="btn btn-outline-danger" type="button" onclick="this.closest('.setting-row').remove()"><i class="bi bi-trash"></i></button></div><?php endforeach;?></div><div class="text-end mt-3"><button class="btn btn-warning px-4" <?=$canEdit?'':'disabled'?>>Lưu toàn bộ cài đặt</button></div></section></form>
