function toggleRoomFields(c){c.closest('.room-select').querySelectorAll('.room-fields input').forEach(i=>i.disabled=!c.checked)}function toggleRooms(on){document.querySelectorAll('.room-check').forEach(c=>{c.checked=on;toggleRoomFields(c)})}function syncDefaultPoints(){var s=document.getElementById('batchCriterion'),o=s.options[s.selectedIndex],p=o?o.dataset.points:'';if(!p)return;document.querySelectorAll('.room-points').forEach(i=>i.value=p)}function addRatingRow(){var r=document.createElement('div');r.className='rating-row';r.innerHTML='<input class="form-control" name="rating_name[]" placeholder="Tên xếp loại" required><input class="form-control" type="number" min="0" step=".1" name="rating_min[]" value="0" required><select class="form-select" name="rating_color[]"><option value="success">Xanh lá</option><option value="primary">Xanh dương</option><option value="warning">Vàng</option><option value="danger">Đỏ</option><option value="secondary">Xám</option></select><button class="btn btn-outline-danger" type="button" onclick="this.closest(\'.rating-row\').remove()"><i class="bi bi-trash"></i></button>';document.getElementById('ratingRows').appendChild(r)}function addSettingRow(){var r=document.createElement('div');r.className='setting-row';r.innerHTML='<input class="form-control criterion-id" name="criterion_id[]" readonly placeholder="Tự tạo"><input class="form-control" name="criterion_name[]" placeholder="Nội dung chấm" required><input class="form-control" type="number" min=".01" step=".01" name="criterion_points[]" value="1" required><select class="form-select" name="criterion_active[]"><option value="1">Hiển thị</option><option value="0">Ẩn</option></select><button class="btn btn-outline-danger" type="button" onclick="this.closest(\'.setting-row\').remove()"><i class="bi bi-trash"></i></button>';document.getElementById('settingRows').appendChild(r)}
</script></body></html>
